<?php
namespace Nakhostin\PerformanceEngine\Assets;
final class AssetUsagePlanner { public function plan( AssetRegistry $registry, array $evidence, bool $safe_mode = true ): array { $assets = $registry->all(); $graph = new AssetDependencyGraph( $assets ); $required = array_values( array_unique( array_map( 'sanitize_key', (array) ( $evidence['required'] ?? array() ) ) ) ); $absent = array_values( array_unique( array_map( 'sanitize_key', (array) ( $evidence['explicitly_absent'] ?? array() ) ) ) ); $decisions = array(); foreach ( $assets as $handle => $asset ) { if ( in_array( $handle, $required, true ) ) { $decisions[ $handle ] = ( new AssetDecision( $handle, AssetDecision::KEEP, 'required-by-page-or-component', 100 ) )->to_array(); } elseif ( ! $safe_mode && in_array( $handle, $absent, true ) && $graph->can_unload( $handle, $required ) ) { $decisions[ $handle ] = ( new AssetDecision( $handle, AssetDecision::UNLOAD, 'component-absent-from-analyzed-page', 95 ) )->to_array(); } else { $decisions[ $handle ] = ( new AssetDecision( $handle, AssetDecision::KEEP, 'unknown-state-falls-back-to-keep', 0 ) )->to_array(); } } return $decisions; } }
